use std::{
    fs,
    io::{self, Write},
    path::{Path, PathBuf},
    process::{Command, Stdio},
    time::Instant,
};

use crate::{
    generator::{
        id::{EndSlot, NonterminalIds, SlotIds, TerminalIds},
        parser_gen::ParserGen,
    },
    grammar::{def::Grammar, slot::Slot},
};

pub struct GenConfig {
    pub ll1_optimization: bool,
    /// Run rustfmt on generated files. Disable to skip the subprocess call
    /// (e.g. for tests that don't care about formatting, or when rustfmt
    /// is unavailable).
    pub run_rustfmt: bool,
}

impl Default for GenConfig {
    fn default() -> Self {
        Self {
            ll1_optimization: true,
            run_rustfmt: true,
        }
    }
}

pub struct GenerateResult {
    pub total_duration_ms: u64,
}

mod cargo_toml_gen;
mod grammar_data_gen;
pub(crate) mod grammar_utils;
mod id;
mod lib_gen;
mod main_gen;
mod parse_tree_gen;
