mod scanner_gen;
mod types_gen;
pub(crate) mod utils;

const GENERATED_HEADER_RUST: &str = "// @generated by iguana. Do not edit manually.\n\n";

/// Generate parser source files into `<output_dir>/src/`.
///
/// Writes lib.rs, parser.rs, scanner.rs, parse_tree.rs, types.rs, and
/// grammar_data.rs. Does not touch Cargo.toml or main.rs — those are
/// scaffolded once by `generate_scaffold` and owned by the user thereafter.
pub fn generate_sources(
    grammar: &Grammar,
    output_dir: &Path,
    config: GenConfig,
) -> io::Result<GenerateResult> {
    let start = Instant::now();
    let mut nonterminal_ids = NonterminalIds::new(grammar.nonterminals().cloned());
    let mut terminal_ids = TerminalIds::default();
    for terminal in grammar.terminals() {
        terminal_ids.insert(terminal.clone());
    }
    let mut slot_ids = SlotIds::new(grammar);
    for nonterminal in grammar.nonterminals() {
        let alternatives = grammar.alternatives(nonterminal);
        for (index, alternative) in alternatives.iter().enumerate() {
            for pos in 0..alternative.symbols.len() {
                let slot = Slot::new(nonterminal, alternative, pos);
                slot_ids.insert(slot);
            }
            let last_symbol_index = alternative.symbols.len();
            let end_slot = Slot::new(nonterminal, alternative, last_symbol_index);
            let end_slot_id = slot_ids.insert(end_slot);
            let nonterminal_id = nonterminal_ids.get_id(nonterminal);
            let end_slot = EndSlot {
                index,
                slot_id: end_slot_id,
            };
            nonterminal_ids.add_end_slot(nonterminal_id, end_slot);
        }
    }

    if !output_dir.exists() {
        fs::create_dir_all(output_dir)?;
    }
    let src_dir = output_dir.join("src");
    if !src_dir.exists() {
        fs::create_dir(&src_dir)?;
    }

    let lib_path = src_dir.join("lib.rs");
    let parser_path = src_dir.join("parser.rs");
    let scanner_path = src_dir.join("scanner.rs");
    let parse_tree_path = src_dir.join("parse_tree.rs");
    let types_path = src_dir.join("types.rs");
    let grammar_data_path = src_dir.join("grammar_data.rs");

    write_rust_file(
        rewrite_attrs(&lib_gen::generate(grammar).to_string()),
        &lib_path,
    )?;

    let run_rustfmt = config.run_rustfmt;
    let mut parser_gen =
        ParserGen::new(grammar, &nonterminal_ids, &terminal_ids, &slot_ids, config);
    let parser_code = parser_gen.generate();
    let grammar_comment = grammar
        .to_string()
        .lines()
        .map(|l| format!("// {l}"))
        .collect::<Vec<_>>()
        .join("\n");
    let parser_source = format!(
        "{grammar_comment}\n{}",
        rewrite_attrs(&parser_code.to_string())
    );
    write_rust_file(parser_source, &parser_path)?;

    write_rust_file(
        rewrite_attrs(&scanner_gen::generate(grammar, &terminal_ids).to_string()),
        &scanner_path,
    )?;

    write_rust_file(
        rewrite_attrs(
            &parse_tree_gen::generate(grammar, &nonterminal_ids, &terminal_ids, &slot_ids)
                .to_string(),
        ),
        &parse_tree_path,
    )?;

    write_rust_file(
        rewrite_attrs(&types_gen::generate().to_string()),
        &types_path,
    )?;

    write_rust_file(
        rewrite_attrs(
            &grammar_data_gen::generate(grammar, &nonterminal_ids, &terminal_ids, &slot_ids)
                .to_string(),
        ),
        &grammar_data_path,
    )?;

    if run_rustfmt {
        format_files(&[
            lib_path,
            parser_path,
            scanner_path,
            parse_tree_path,
            types_path,
            grammar_data_path,
        ])?;
    }

    Ok(GenerateResult {
        total_duration_ms: start.elapsed().as_millis() as u64,
    })
}

/// Scaffold Cargo.toml and src/main.rs into `output_dir`.
///
/// Idempotent: each file is written only if it does not already exist.
/// The user owns these files after first creation; subsequent grammar
/// changes do not regenerate them.
pub fn generate_scaffold(grammar: &Grammar, output_dir: &Path) -> io::Result<()> {
    if !output_dir.exists() {
        fs::create_dir_all(output_dir)?;
    }
    let src_dir = output_dir.join("src");
    if !src_dir.exists() {
        fs::create_dir(&src_dir)?;
    }

    let cargo_toml = output_dir.join("Cargo.toml");
    if !cargo_toml.exists() {
        write_plain_file(cargo_toml_gen::generate(grammar), &cargo_toml)?;
    }

    let main_rs = src_dir.join("main.rs");
    if !main_rs.exists() {
        let main_code = main_gen::generate(grammar);
        write_plain_file(rewrite_attrs(&main_code.to_string()), &main_rs)?;
        format_files(&[main_rs])?;
    }

    Ok(())
}

fn write_rust_file(content: impl AsRef<str>, path: &Path) -> io::Result<()> {
    let mut file = fs::File::create(path)?;
    file.write_all(GENERATED_HEADER_RUST.as_bytes())?;
    file.write_all(content.as_ref().as_bytes())?;
    file.write_all(b"\n")?;
    Ok(())
}

/// Run rustfmt on the given files, one process per file in parallel.
fn format_files(paths: &[PathBuf]) -> io::Result<()> {
    if paths.is_empty() {
        return Ok(());
    }
    std::thread::scope(|s| -> io::Result<()> {
        let handles: Vec<_> = paths
            .iter()
            .map(|p| s.spawn(move || format_file(p)))
            .collect();
        for h in handles {
            h.join()
                .map_err(|_| io::Error::other("rustfmt thread panicked"))??;
        }
        Ok(())
    })
}

/// Format a single file by piping its contents through rustfmt's stdin.
///
/// We deliberately avoid `rustfmt <path>` because rustfmt enters "project
/// mode" when given a path: it walks `mod foo;` declarations and reads
/// the corresponding sibling files to validate the mod tree. Running
/// multiple such invocations in parallel on files of the same crate
/// races — one rustfmt may read a sibling while another truncates it
/// for output, producing the error
/// `failed to resolve mod 'foo': cannot parse foo.rs` and leaving files
/// corrupted.
///
/// Stdin mode (`Operation::Stdin` → `Input::Text`) has no file location to
/// anchor mod resolution against, so siblings are not touched. We do the
/// read/write ourselves and pipe the source through rustfmt as bytes.
///
/// Passes `--edition 2024` because rustfmt's CLI default is edition 2015,
/// which produces subtly different formatting than the workspace's edition.
/// Stdin mode has no Cargo.toml to infer the edition from, so we must be
/// explicit.
///
/// References:
///   https://github.com/rust-lang/rustfmt/blob/master/README.md
///   https://github.com/rust-lang/rustfmt/issues/562
///   https://github.com/rust-lang/rustfmt/issues/5024
fn format_file(path: &Path) -> io::Result<()> {
    let input = fs::read_to_string(path)?;
    let formatted = rustfmt_string(&input)
        .map_err(|e| io::Error::other(format!("rustfmt failed on {}: {}", path.display(), e)))?;
    fs::write(path, formatted)
}

/// Pipe `input` through rustfmt via stdin/stdout. Returns the formatted source.
pub fn rustfmt_string(input: &str) -> io::Result<String> {
    let mut child = Command::new("rustfmt")
        .arg("--edition")
        .arg("2024")
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()?;

    // Drop stdin after writing so rustfmt sees EOF and returns.
    child.stdin.take().unwrap().write_all(input.as_bytes())?;

    let output = child.wait_with_output()?;
    if !output.status.success() {
        return Err(io::Error::other(
            String::from_utf8_lossy(&output.stderr).trim().to_string(),
        ));
    }
    String::from_utf8(output.stdout).map_err(io::Error::other)
}

fn write_plain_file(content: impl AsRef<str>, path: &Path) -> io::Result<()> {
    let mut file = fs::File::create(path)?;
    file.write_all(content.as_ref().as_bytes())?;
    file.write_all(b"\n")?;
    Ok(())
}

/// Rewrite attribute pseudo-syntax in generated code into the cleaner forms.
///
/// Two transformations:
/// - `#[comment = "..."]` (our pseudo-attribute, not real Rust) → `// ...`.
/// - `#[doc = r"..."]` / `#[doc = r#"..."#]` (quote!'s default rendering of
///   `///` doc lines) → `/// ...`. The attribute form is valid Rust but
///   noisy; restoring `///` keeps generated code legible.
///
/// `#[comment]` is not a real attribute, so any unrewritten occurrence would
/// be a compile error. Run this on every generator output that goes to disk.
fn rewrite_attrs(input: &str) -> String {
    let s = replace_comment_attrs(input);
    desugar_doc_attrs(&s)
}

fn replace_comment_attrs(input: &str) -> String {
    use std::sync::OnceLock;
    static RE: OnceLock<regex::Regex> = OnceLock::new();
    let re = RE.get_or_init(|| {
        regex::Regex::new(r#"#\s*\[\s*comment\s*=\s*"((?:[^"\\]|\\.)*)"\s*\]"#).unwrap()
    });
    re.replace_all(input, |caps: &regex::Captures| {
        format!("\n// {}\n", unescape(&caps[1]))
    })
    .into_owned()
}

fn desugar_doc_attrs(input: &str) -> String {
    use std::sync::OnceLock;
    static RE_RAW_HASH: OnceLock<regex::Regex> = OnceLock::new();
    static RE_RAW: OnceLock<regex::Regex> = OnceLock::new();
    let raw_hash = RE_RAW_HASH
        .get_or_init(|| regex::Regex::new(r##"#\s*\[\s*doc\s*=\s*r#"(.*?)"#\s*\]"##).unwrap());
    let raw = RE_RAW
        .get_or_init(|| regex::Regex::new(r#"#\s*\[\s*doc\s*=\s*r"([^"]*)"\s*\]"#).unwrap());
    let s = raw_hash
        .replace_all(input, |caps: &regex::Captures| format!("\n///{}\n", &caps[1]))
        .into_owned();
    raw.replace_all(&s, |caps: &regex::Captures| format!("\n///{}\n", &caps[1]))
        .into_owned()
}

/// The regex captures the *source-text* inside a string literal, so escape
/// sequences are still in their escaped form (`\"`, `\\`, `\n`, …). Line
/// comments don't interpret escapes — leaving them as-is would render
/// `#[comment = "He said \"hi\""]` as `// He said \"hi\"` (with literal
/// backslashes) rather than `// He said "hi"`. Decode them back to the
/// real string value before splicing into the comment.
fn unescape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        if c == '\\' {
            match chars.next() {
                Some('n') => out.push('\n'),
                Some('t') => out.push('\t'),
                Some('"') => out.push('"'),
                Some('\\') => out.push('\\'),
                Some(other) => {
                    out.push('\\');
                    out.push(other);
                }
                None => out.push('\\'),
            }
        } else {
            out.push(c);
        }
    }
    out
}
